window.docContents[216].resolve({"/Postscript/#Logical-Foundations--Postscript--Resources":{"contents":"This volume also contains optional sections and exercises that develop\nsome topics further.\n\nFor questions about Lean, the\nLean community Zulip is an active\nplace to ask questions and discuss formalization.\n\nThe following books continue in several different directions:\n\n* Functional Programming in Lean\n  explores Lean as a programming language.* Theorem Proving in Lean 4\n  gives a systematic introduction to Lean's logic and proof language.* Mathematics in Lean\n  develops formalized mathematics using Lean and Mathlib.\n\n\n","context":"Logical Foundations\u0009Postscript","header":"12.3. Resources","id":"/Postscript/#Logical-Foundations--Postscript--Resources"}});